// uts_clone.c - compile with: gcc -o uts_clone uts_clone.c
#define _GNU_SOURCE
#include <sched.h>
#include <stdio.h>
#include <unistd.h>
#include <sys/wait.h>

static int child_fn(void *arg) {
    printf("child: in new UTS namespace\n");
    sethostname("cloned-ns", 9);   /* requires CAP_SYS_ADMIN */
    execlp("/bin/hostname", "hostname", NULL);
    return 0;
}

int main(void) {
    char *stack = malloc(65536);
    if (!stack) return 1;
    printf("parent: hostname is ");
    fflush(stdout);
    system("hostname");

    pid_t pid = clone(child_fn, stack + 65536,
                      CLONE_NEWUTS | SIGCHLD, NULL);
    waitpid(pid, NULL, 0);
    printf("parent: hostname is still ");
    system("hostname");
    free(stack);
    return 0;
}

# Run as root (sethostname needs CAP_SYS_ADMIN in the new UTS namespace)
user@host:~$ sudo ./uts_clone
parent: hostname is host
child: in new UTS namespace
cloned-ns
parent: hostname is still host

